<?php require __DIR__.'/_init.php'; adminHeader('Dashboard'); ?><p>Your store at a glance. Card payments are simulated.</p><div class="cards"><?php
foreach (['Products'=>'SELECT COUNT(*) FROM products','Categories'=>'SELECT COUNT(*) FROM categories','Customers'=>"SELECT COUNT(*) FROM users WHERE role='user'",'Orders'=>'SELECT COUNT(*) FROM orders','Paid revenue (BDT)'=>"SELECT COALESCE(SUM(total),0) FROM orders WHERE payment_status='paid' AND status <> 'cancelled'"] as $label=>$sql) echo '<div class="card">'.e($label).'<strong>'.e($pdo->query($sql)->fetchColumn()).'</strong></div>';
?><h2>Recent orders</h2><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th></tr><?php foreach($pdo->query('SELECT o.*,u.name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC LIMIT 8') as $r): ?><tr><td><a href="orders/view.php?id=<?= (int)$r['id'] ?>">#<?= (int)$r['id'] ?></a></td><td><?= e($r['name']) ?></td><td>৳<?= e($r['total']) ?></td><td><?= e($r['status']) ?></td></tr><?php endforeach ?></table><?php adminFooter(); ?>